// ═══ 音效系统 ═══
var _ac=null,audioMaster=null,soundEnabled=true;
try{soundEnabled=localStorage.getItem('llk_sound')!=='off';}catch(e){}
function updateSoundButton(){
  var button=document.getElementById('sound-toggle');
  button.textContent=soundEnabled?'🔊 声音：开':'🔇 声音：关';
  button.setAttribute('aria-pressed',String(soundEnabled));
}
function toggleSound(){
  soundEnabled=!soundEnabled;
  try{localStorage.setItem('llk_sound',soundEnabled?'on':'off');}catch(e){}
  if(audioMaster)audioMaster.gain.setValueAtTime(soundEnabled?1:0,_ac.currentTime);
  updateSoundButton();
}
var fallBgmNode=null, fallBgmRequest=0, fallBgmBuffer=null;
function preloadFallBGM(context){
  if(!fallBgmBuffer){
    fallBgmBuffer=fetch('data:audio/mpeg;base64,')
      .then(function(response){
        if(!response.ok)throw Error('Cannot load fall music');
        return response.arrayBuffer();
      })
      .then(function(bytes){return context.decodeAudioData(bytes);})
      .catch(function(){fallBgmBuffer=null;return null;});
  }
  return fallBgmBuffer;
}

function getAC(){
  if(!_ac){_ac=new(window.AudioContext||window.webkitAudioContext)();audioMaster=_ac.createGain();audioMaster.gain.value=soundEnabled?1:0;audioMaster.connect(_ac.destination);preloadFallBGM(_ac);}
  if(_ac.state==='suspended') _ac.resume();
  return _ac;
}

// 通用音调播放
function playTones(freqs,type,vol,dur){
  try{var a=getAC(),t=a.currentTime,d=dur||0.2,v=vol||0.28;
    freqs.forEach(function(f,i){
      var o=a.createOscillator(),g=a.createGain();
      o.connect(g);g.connect(audioMaster);
      o.type=type||'sine';o.frequency.value=f;
      g.gain.setValueAtTime(0,t+i*0.09);
      g.gain.linearRampToValueAtTime(v,t+i*0.09+0.02);
      g.gain.exponentialRampToValueAtTime(0.001,t+i*0.09+d);
      o.start(t+i*0.09);o.stop(t+i*0.09+d+0.05);
    });
  }catch(e){}
}

// ── 连连看音效 ──
function playMatch(){playTones([523,659,784,1047],'sine',0.25,0.18);}
function playClear(){
  // 胜利上升音阶
  try{var a=getAC(),t=a.currentTime;
    [523,587,659,698,784,880,988,1047].forEach(function(f,i){
      var o=a.createOscillator(),g=a.createGain();
      o.connect(g);g.connect(audioMaster);o.type='sine';o.frequency.value=f;
      g.gain.setValueAtTime(0,t+i*0.07);g.gain.linearRampToValueAtTime(0.3,t+i*0.07+0.03);
      g.gain.exponentialRampToValueAtTime(0.001,t+i*0.07+0.25);
      o.start(t+i*0.07);o.stop(t+i*0.07+0.3);
    });
  }catch(e){}
}
function playCorrect(){
  // 答对：欢快上升
  playTones([523,659,784,1047,1319],'triangle',0.3,0.15);
}
function playWrong(){
  // 答错：沉闷下降
  try{var a=getAC(),t=a.currentTime;
    [400,320,250].forEach(function(f,i){
      var o=a.createOscillator(),g=a.createGain();
      o.connect(g);g.connect(audioMaster);o.type='sawtooth';o.frequency.value=f;
      g.gain.setValueAtTime(0.25,t+i*0.12);g.gain.exponentialRampToValueAtTime(0.001,t+i*0.12+0.25);
      o.start(t+i*0.12);o.stop(t+i*0.12+0.3);
    });
  }catch(e){}
}
function playHint(){
  // 提示：轻柔提醒
  playTones([880,1047],'sine',0.15,0.3);
}
function playShuffle(){
  // 洗牌：随机感
  try{var a=getAC(),t=a.currentTime;
    for(var i=0;i<6;i++){
      var f=300+Math.random()*800;
      var o=a.createOscillator(),g=a.createGain();
      o.connect(g);g.connect(audioMaster);o.type='square';o.frequency.value=f;
      g.gain.setValueAtTime(0.1,t+i*0.05);g.gain.exponentialRampToValueAtTime(0.001,t+i*0.05+0.08);
      o.start(t+i*0.05);o.stop(t+i*0.05+0.1);
    }
  }catch(e){}
}
function playTimerWarn(){
  // 倒计时警告：急促
  try{var a=getAC(),t=a.currentTime;
    var o=a.createOscillator(),g=a.createGain();
    o.connect(g);g.connect(audioMaster);o.type='square';o.frequency.value=880;
    g.gain.setValueAtTime(0.15,t);g.gain.exponentialRampToValueAtTime(0.001,t+0.1);
    o.start(t);o.stop(t+0.12);
  }catch(e){}
}
function playWrongClick(){
  // 点错：短促警告
  try{var a=getAC(),t=a.currentTime;
    var o=a.createOscillator(),g=a.createGain();
    o.connect(g);g.connect(audioMaster);o.type='sawtooth';o.frequency.value=220;
    g.gain.setValueAtTime(0.3,t);g.gain.exponentialRampToValueAtTime(0.001,t+0.3);
    o.start(t);o.stop(t+0.35);
  }catch(e){}
}
function playQuizReveal(){
  // 答题揭示：神秘感
  playTones([440,554,659],'sine',0.2,0.4);
}

// ── 惩罚游戏平台音效 ──
function sfxBounce(){
  // 绿色安全平台弹跳：弹簧感
  try{var a=getAC(),t=a.currentTime;
    var o=a.createOscillator(),g=a.createGain();
    o.connect(g);g.connect(audioMaster);
    o.type='sine';o.frequency.setValueAtTime(300,t);
    o.frequency.exponentialRampToValueAtTime(600,t+0.08);
    g.gain.setValueAtTime(0.4,t);g.gain.exponentialRampToValueAtTime(0.001,t+0.2);
    o.start(t);o.stop(t+0.22);
  }catch(e){}
}
function sfxBreak(){
  // 橙色破碎平台：碎裂声
  try{var a=getAC(),t=a.currentTime;
    // 噪声+低音
    var buf=a.createBuffer(1,a.sampleRate*0.3,a.sampleRate);
    var data=buf.getChannelData(0);
    for(var i=0;i<data.length;i++) data[i]=(Math.random()*2-1)*Math.pow(1-i/data.length,2);
    var src=a.createBufferSource();src.buffer=buf;
    var f=a.createBiquadFilter();f.type='bandpass';f.frequency.value=800;f.Q.value=0.5;
    var g=a.createGain();g.gain.setValueAtTime(0.5,t);g.gain.exponentialRampToValueAtTime(0.001,t+0.3);
    src.connect(f);f.connect(g);g.connect(audioMaster);src.start(t);src.stop(t+0.32);
  }catch(e){}
}
function sfxSlide(){
  // 蓝色移动平台：机械"咔哒"弹跳感
  try{var a=getAC(),t=a.currentTime;
    // 两声短促方波咔哒
    [0,0.08].forEach(function(off){
      var o=a.createOscillator(),g=a.createGain();
      o.connect(g);g.connect(audioMaster);
      o.type='square';o.frequency.value=320;
      g.gain.setValueAtTime(0.25,t+off);
      g.gain.exponentialRampToValueAtTime(0.001,t+off+0.06);
      o.start(t+off);o.stop(t+off+0.08);
    });
    // 加一个短促上扫
    var o2=a.createOscillator(),g2=a.createGain();
    o2.connect(g2);g2.connect(audioMaster);
    o2.type='sine';
    o2.frequency.setValueAtTime(200,t+0.05);
    o2.frequency.linearRampToValueAtTime(440,t+0.18);
    g2.gain.setValueAtTime(0.15,t+0.05);g2.gain.exponentialRampToValueAtTime(0.001,t+0.2);
    o2.start(t+0.05);o2.stop(t+0.22);
  }catch(e){}
}
function sfxSpike(){
  // 红色尖刺：死亡音效
  try{var a=getAC(),t=a.currentTime;
    [220,180,150,120].forEach(function(f,i){
      var o=a.createOscillator(),g=a.createGain();
      o.connect(g);g.connect(audioMaster);o.type='sawtooth';o.frequency.value=f;
      g.gain.setValueAtTime(0.5,t+i*0.05);g.gain.exponentialRampToValueAtTime(0.001,t+i*0.05+0.3);
      o.start(t+i*0.05);o.stop(t+i*0.05+0.35);
    });
  }catch(e){}
}
function sfxFall(){
  // 坠落音效
  try{var a=getAC(),t=a.currentTime;
    var o=a.createOscillator(),g=a.createGain();
    o.connect(g);g.connect(audioMaster);o.type='sine';
    o.frequency.setValueAtTime(800,t);
    o.frequency.exponentialRampToValueAtTime(80,t+0.5);
    g.gain.setValueAtTime(0.4,t);g.gain.exponentialRampToValueAtTime(0.001,t+0.6);
    o.start(t);o.stop(t+0.65);
  }catch(e){}
}
function sfxVictory(){
  // 惩罚游戏通关：胜利
  try{var a=getAC(),t=a.currentTime;
    [[523,0],[659,0.1],[784,0.2],[1047,0.35],[784,0.5],[1047,0.65],[1319,0.8]].forEach(function(p){
      var o=a.createOscillator(),g=a.createGain();
      o.connect(g);g.connect(audioMaster);o.type='triangle';o.frequency.value=p[0];
      g.gain.setValueAtTime(0,t+p[1]);g.gain.linearRampToValueAtTime(0.3,t+p[1]+0.02);
      g.gain.exponentialRampToValueAtTime(0.001,t+p[1]+0.25);
      o.start(t+p[1]);o.stop(t+p[1]+0.3);
    });
  }catch(e){}
}

// Arcade descent loop
function startFallBGM(){
  stopFallBGM();
  var context=getAC(),request=fallBgmRequest;
  preloadFallBGM(context).then(function(buffer){
    if(!buffer || request!==fallBgmRequest)return;
    var source=context.createBufferSource(),volume=context.createGain();
    source.buffer=buffer;
    source.loop=true;
    volume.gain.value=.42;
    source.connect(volume);
    volume.connect(audioMaster);
    source.onended=function(){source.disconnect();volume.disconnect();};
    fallBgmNode=source;
    source.start();
  });
}
function stopFallBGM(){
  fallBgmRequest++;
  if(fallBgmNode){fallBgmNode.stop();fallBgmNode=null;}
}

// Cheerful original 116 BPM plucked melody; no external music requests.
var matchBgm=null;
function stopMatchBGM(){if(!matchBgm)return;clearInterval(matchBgm.timer);try{matchBgm.bus.disconnect();}catch(e){}matchBgm=null;}
function duckMatchBGM(active){if(matchBgm)matchBgm.bus.gain.setTargetAtTime(active?.025:.095,getAC().currentTime,.12);}
function startMatchBGM(){if(matchBgm)return;try{var a=getAC(),bus=a.createGain();bus.gain.value=.095;bus.connect(audioMaster);var next=a.currentTime+.03,index=0,step=60/116/2;
var melody=[72,76,79,0,76,74,72,0,69,72,76,0,74,72,69,0,65,69,72,0,76,72,69,0,67,71,74,79,76,74,71,0];
function pluck(midi,t,duration,level){var o=a.createOscillator(),g=a.createGain();o.type='triangle';o.frequency.value=440*Math.pow(2,(midi-69)/12);o.connect(g);g.connect(bus);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(level,t+.008);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.start(t);o.stop(t+duration+.02);o.onended=function(){o.disconnect();g.disconnect();};}
function schedule(){if(next<a.currentTime)next=a.currentTime+.02;while(next<a.currentTime+.2){var i=index%32;if(melody[i])pluck(melody[i],next,step*.8,.45);if(i%4===0)pluck([48,45,41,43][Math.floor(i/8)],next,step*1.5,.5);if(i%4===2)pluck([60,57,53,55][Math.floor(i/8)],next,step*.4,.2);next+=step;index++;}}
matchBgm={bus:bus,timer:setInterval(schedule,80)};schedule();}catch(e){stopMatchBGM();}}
